theorem bending_cannot_carry {F ℓ Z : ℝ → ℝ} {kF kℓ kZ σmax n : ℝ} (hF : CubeLaw F kF) (hℓ : LeverLaw ℓ kℓ)
    (hZ : SectionModulusLaw Z kZ) (hσ : 0 < σmax) (hn : 0 < n) {L : ℝ}
    (hL : σmax * kZ / (kF * kℓ * n) < L) : σmax < n * bendingStress F ℓ Z L

